{
  "findings": [
    {
      "check_id": "CKV2_AZURE_33",
      "title": "Ensure storage account is configured with private endpoint",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account is not configured with a private endpoint, which could expose it to public network access."
    },
    {
      "check_id": "CKV2_AZURE_38",
      "title": "Ensure soft-delete is enabled on Azure storage account",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "Soft-delete is not enabled, which could result in permanent data loss if data is accidentally or maliciously deleted."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Ensure storage account is configured without blob anonymous access",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "Blob anonymous access is not explicitly disabled, which could allow unauthorized access to data."
    },
    {
      "check_id": "CKV_AZURE_36",
      "title": "Ensure 'Trusted Microsoft Services' is enabled for Storage Account access",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "Trusted Microsoft Services are not enabled, which could prevent secure integration with Microsoft services."
    },
    {
      "check_id": "CKV2_AZURE_41",
      "title": "Ensure storage account is configured with SAS expiration policy",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account does not have a SAS expiration policy, which could lead to long-lived or indefinite access tokens."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"notification_storage\" {\n  name                     = \"smartgridscada${random_string.suffix.result}\"\n  resource_group_name      = azurerm_resource_group.smart_grid_rg.name\n  location                 = azurerm_resource_group.smart_grid_rg.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"LRS\"\n  enable_https_traffic_only = true\n\n  network_rules {\n    default_action             = \"Deny\"\n    bypass                     = [\"AzureServices\"]\n  }\n\n  blob_properties {\n    delete_retention_policy {\n      days = 7\n    }\n  }\n\n  allow_blob_public_access = false\n\n  shared_access_key_expiration_policy {\n    expiration_period_in_days = 7\n  }\n}\n",
  "fix_summary": "Enabled HTTPS traffic only, added network rules to restrict public access and allow Trusted Microsoft Services, enabled soft-delete with a 7-day retention policy, disabled blob anonymous access, and configured a SAS expiration policy with a 7-day limit."
}
